-- USD-only organization accounting. Existing journals and financial rows remain intact.
CREATE TABLE acc_roles(user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('accountant','approver','auditor')),PRIMARY KEY(user_id,role));
CREATE TABLE acc_account_profiles(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id),effective_date TEXT NOT NULL,name TEXT NOT NULL,reporting_type TEXT NOT NULL CHECK(reporting_type IN('asset','liability','net_assets','income','expense')),reporting_group TEXT NOT NULL,control_role TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL CHECK(active IN(0,1)),cash_flow TEXT NOT NULL CHECK(cash_flow IN('operating','investing','financing','cash','noncash')),reason TEXT NOT NULL,actor_id INTEGER REFERENCES users(id));
INSERT INTO accounts(code,name,type) VALUES('3100','Accumulated funds','funding'),('4000','Recognized funding income','funding'),('2300','Deferred conditional funding','payable'),('2310','Refundable funding','payable'),('1590','Accumulated depreciation','asset'),('5400','Depreciation expense','expense');
INSERT INTO acc_account_profiles(account_id,effective_date,name,reporting_type,reporting_group,control_role,active,cash_flow,reason)
SELECT id,'0001-01-01',name,CASE WHEN type IN('bank','cash','mobile','asset','advance') THEN 'asset' WHEN type='payable' OR code='3000' THEN 'liability' WHEN code='3100' THEN 'net_assets' WHEN code='4000' THEN 'income' ELSE 'expense' END,
CASE WHEN type IN('bank','cash','mobile') THEN 'Cash and cash equivalents' WHEN code IN('1500','1590') THEN 'Property and equipment' WHEN code='1400' THEN 'Inventory' WHEN code='2000' THEN 'Supplier payables' WHEN code IN('2100','2110','2120') THEN 'Payroll liabilities' WHEN code IN('3000','2300','2310') THEN 'Funding liabilities' WHEN code IN('1200','1250','1300') THEN 'Advances and receivables' WHEN code='3100' THEN 'Accumulated funds' WHEN code='4000' THEN 'Funding income' WHEN code='5100' THEN 'Personnel costs' ELSE 'Operating costs' END,
CASE code WHEN '3000' THEN 'funding_control' WHEN '3100' THEN 'fund_balance' WHEN '4000' THEN 'funding_income' WHEN '2300' THEN 'funding_deferred' WHEN '2310' THEN 'funding_refundable' WHEN '2000' THEN 'supplier_liability' WHEN '1200' THEN 'spending_advance' WHEN '1250' THEN 'salary_advance' WHEN '1300' THEN 'supplier_refund' WHEN '2100' THEN 'payroll_net' WHEN '2110' THEN 'payroll_statutory' WHEN '2120' THEN 'payroll_other' WHEN '5100' THEN 'payroll_expense' WHEN '1500' THEN 'capital_asset' WHEN '1590' THEN 'accumulated_depreciation' WHEN '5400' THEN 'depreciation_expense' WHEN '1400' THEN 'inventory' WHEN '5300' THEN 'inventory_variance' WHEN '5000' THEN 'expenditure' ELSE CASE WHEN type IN('bank','cash','mobile') THEN 'cash' ELSE '' END END,1,
CASE WHEN type IN('bank','cash','mobile') THEN 'cash' WHEN code IN('1500','1590','1400') THEN 'investing' WHEN code='3100' THEN 'financing' WHEN code='5400' THEN 'noncash' ELSE 'operating' END,'Preserved initial account mapping' FROM accounts;
CREATE TABLE acc_mappings(id INTEGER PRIMARY KEY,role TEXT NOT NULL,account_id INTEGER NOT NULL REFERENCES accounts(id),effective_date TEXT NOT NULL,actor_id INTEGER REFERENCES users(id),reason TEXT NOT NULL);
INSERT INTO acc_mappings(role,account_id,effective_date,reason) SELECT control_role,account_id,'0001-01-01','Existing posting account' FROM acc_account_profiles WHERE control_role<>'' AND control_role<>'cash';
CREATE TABLE acc_books(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),actor_id INTEGER REFERENCES users(id));
INSERT INTO acc_books(code,name,active) VALUES('GEN','General journal',1);
CREATE TABLE acc_journal_info(journal_id INTEGER PRIMARY KEY REFERENCES journals(id),book_id INTEGER NOT NULL REFERENCES acc_books(id),currency TEXT NOT NULL CHECK(currency='USD'),original_amount INTEGER NOT NULL,base_amount INTEGER NOT NULL,rate TEXT NOT NULL CHECK(rate='1'),rate_date TEXT NOT NULL,source_kind TEXT NOT NULL,source_record TEXT NOT NULL,CHECK(original_amount=base_amount));
INSERT INTO acc_journal_info SELECT j.id,1,'USD',COALESCE((SELECT SUM(amount) FROM journal_lines l WHERE l.journal_id=j.id AND amount>0),0),COALESCE((SELECT SUM(amount) FROM journal_lines l WHERE l.journal_id=j.id AND amount>0),0),'1',j.date,j.kind,j.reference FROM journals j;
CREATE TABLE acc_line_roles(line_id INTEGER PRIMARY KEY REFERENCES journal_lines(id),role TEXT NOT NULL);
INSERT INTO acc_line_roles SELECT l.id,p.control_role FROM journal_lines l JOIN acc_account_profiles p ON p.account_id=l.account_id;
CREATE TABLE acc_fiscal_years(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,start_date TEXT NOT NULL,end_date TEXT NOT NULL,actor_id INTEGER REFERENCES users(id),CHECK(start_date<=end_date));
CREATE TABLE acc_fiscal_periods(period_id INTEGER PRIMARY KEY REFERENCES periods(id),year_id INTEGER NOT NULL REFERENCES acc_fiscal_years(id));
INSERT INTO acc_fiscal_years(code,start_date,end_date) SELECT 'FY-'||substr(start_date,1,4),start_date,end_date FROM periods WHERE substr(start_date,6)='01-01' AND substr(end_date,6)='12-31' AND substr(start_date,1,4)=substr(end_date,1,4);
INSERT INTO acc_fiscal_periods SELECT p.id,y.id FROM periods p JOIN acc_fiscal_years y ON p.start_date>=y.start_date AND p.end_date<=y.end_date;
CREATE TABLE acc_fund_policies(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES funding_sources(id),effective_date TEXT NOT NULL,restricted INTEGER NOT NULL CHECK(restricted IN(0,1)),receipt_treatment TEXT NOT NULL CHECK(receipt_treatment IN('income','deferred','refundable')),recognition_basis TEXT NOT NULL CHECK(recognition_basis IN('on_receipt','approved_milestone','eligible_expenditure')),allow_transfers INTEGER NOT NULL CHECK(allow_transfers IN(0,1)),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_fund_approvals(policy_id INTEGER PRIMARY KEY REFERENCES acc_fund_policies(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_receipts(journal_id INTEGER PRIMARY KEY REFERENCES journals(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),policy_id INTEGER REFERENCES acc_fund_policies(id),treatment TEXT NOT NULL CHECK(treatment IN('legacy','income','deferred','refundable')),amount INTEGER NOT NULL CHECK(amount>0));
INSERT INTO acc_receipts SELECT j.id,l.source_id,NULL,'legacy',SUM(l.amount) FROM journals j JOIN journal_lines l ON l.journal_id=j.id JOIN accounts a ON a.id=l.account_id WHERE j.kind='receipt' AND a.type IN('bank','cash','mobile') GROUP BY j.id,l.source_id;
CREATE TABLE acc_documents(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('manual','opening','recognition','reclassification','funding_refund','allocation_transfer','opening_settlement','asset_depreciation','asset_disposal')),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,book_id INTEGER NOT NULL REFERENCES acc_books(id),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,lines TEXT NOT NULL,charges TEXT NOT NULL,details TEXT NOT NULL,replaces_id INTEGER REFERENCES acc_documents(id));
CREATE TABLE acc_posts(document_id INTEGER PRIMARY KEY REFERENCES acc_documents(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE acc_cancellations(document_id INTEGER PRIMARY KEY REFERENCES acc_documents(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_evidence(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES acc_documents(id),filename TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,content_encrypted TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_open_items(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES acc_documents(id),account_id INTEGER NOT NULL REFERENCES accounts(id),project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),amount INTEGER NOT NULL CHECK(amount>0),side TEXT NOT NULL CHECK(side IN('debit','credit')),role TEXT NOT NULL,party TEXT NOT NULL,due_date TEXT NOT NULL,employee_id INTEGER REFERENCES employees(id),supplier_id INTEGER REFERENCES suppliers(id));
CREATE TABLE acc_item_movements(id INTEGER PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES acc_open_items(id),journal_id INTEGER NOT NULL REFERENCES journals(id),amount INTEGER NOT NULL CHECK(amount<>0));
CREATE TABLE acc_period_events(id INTEGER PRIMARY KEY,period_id INTEGER NOT NULL REFERENCES periods(id),kind TEXT NOT NULL CHECK(kind IN('close','reopen')),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),snapshot TEXT NOT NULL);
CREATE TABLE acc_close_authorizations(id INTEGER PRIMARY KEY,period_id INTEGER NOT NULL REFERENCES periods(id),closer_id INTEGER NOT NULL REFERENCES users(id),creator_id INTEGER NOT NULL REFERENCES users(id),expiry TEXT NOT NULL,reason TEXT NOT NULL,fingerprint TEXT NOT NULL,treatments TEXT NOT NULL);
CREATE TABLE acc_close_uses(authorization_id INTEGER PRIMARY KEY REFERENCES acc_close_authorizations(id),event_id INTEGER NOT NULL UNIQUE REFERENCES acc_period_events(id));
CREATE TABLE acc_year_ends(id INTEGER PRIMARY KEY,year_id INTEGER NOT NULL REFERENCES acc_fiscal_years(id),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),snapshot TEXT NOT NULL,previous_id INTEGER REFERENCES acc_year_ends(id));
CREATE TABLE acc_year_approvals(year_end_id INTEGER PRIMARY KEY REFERENCES acc_year_ends(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_reopen_requests(id INTEGER PRIMARY KEY,period_id INTEGER NOT NULL REFERENCES periods(id),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),close_event_id INTEGER REFERENCES acc_period_events(id));
CREATE TABLE acc_reopen_approvals(request_id INTEGER PRIMARY KEY REFERENCES acc_reopen_requests(id),actor_id INTEGER NOT NULL REFERENCES users(id),event_id INTEGER NOT NULL UNIQUE REFERENCES acc_period_events(id));
CREATE TABLE acc_year_reopens(year_end_id INTEGER NOT NULL REFERENCES acc_year_ends(id),period_event_id INTEGER NOT NULL REFERENCES acc_period_events(id),PRIMARY KEY(year_end_id,period_event_id));
CREATE TABLE acc_assets(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,project_id INTEGER NOT NULL REFERENCES projects(id),source_id INTEGER NOT NULL REFERENCES funding_sources(id),bill_line_id INTEGER REFERENCES bill_lines(id),opening_item_id INTEGER REFERENCES acc_open_items(id),cost INTEGER NOT NULL CHECK(cost>0),residual INTEGER NOT NULL CHECK(residual>=0 AND residual<cost),life_months INTEGER NOT NULL CHECK(life_months BETWEEN 1 AND 1200),acquired_date TEXT NOT NULL,in_service_date TEXT NOT NULL,custodian TEXT NOT NULL,location TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),CHECK((bill_line_id IS NOT NULL)!=(opening_item_id IS NOT NULL)),CHECK(in_service_date>=acquired_date));
CREATE TABLE acc_asset_approvals(asset_id INTEGER PRIMARY KEY REFERENCES acc_assets(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_asset_cancellations(asset_id INTEGER PRIMARY KEY REFERENCES acc_assets(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_asset_policies(id INTEGER PRIMARY KEY,effective_date TEXT NOT NULL,depreciation_budget_charge INTEGER NOT NULL CHECK(depreciation_budget_charge IN(0,1)),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_asset_policy_approvals(policy_id INTEGER PRIMARY KEY REFERENCES acc_asset_policies(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_asset_events(id INTEGER PRIMARY KEY,asset_id INTEGER NOT NULL REFERENCES acc_assets(id),date TEXT NOT NULL,custodian TEXT NOT NULL,location TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE acc_depreciation(id INTEGER PRIMARY KEY,asset_id INTEGER NOT NULL REFERENCES acc_assets(id),document_id INTEGER NOT NULL REFERENCES acc_documents(id),amount INTEGER NOT NULL CHECK(amount>0),through_month TEXT NOT NULL,UNIQUE(asset_id,document_id));
CREATE TABLE acc_disposals(id INTEGER PRIMARY KEY,asset_id INTEGER NOT NULL REFERENCES acc_assets(id),document_id INTEGER NOT NULL UNIQUE REFERENCES acc_documents(id),proceeds INTEGER NOT NULL CHECK(proceeds>=0),net_book INTEGER NOT NULL CHECK(net_book>=0));
